ALTER TABLE eam_maintenance_execution ADD reviewer_id BIGINT NULL COMMENT '验收人ID',ADD reviewer_name VARCHAR(150) NULL COMMENT '验收人名称快照',ADD reviewed_at DATETIME(6) NULL COMMENT '验收时间';

ALTER TABLE eam_inspection_execution ADD reviewer_id BIGINT NULL COMMENT '审核人ID';

UPDATE eam_maintenance_execution e SET reviewer_id=(SELECT x.actor_id FROM eam_maintenance_event x WHERE x.tenant_id=e.tenant_id AND x.task_id=e.task_id AND x.action IN ('验收通过','验收打回') ORDER BY x.created_at DESC,x.id DESC LIMIT 1) WHERE COALESCE(e.review_decision,'')<>'' AND e.reviewer_id IS NULL;

UPDATE eam_maintenance_execution e SET reviewer_name=(SELECT x.actor_name FROM eam_maintenance_event x WHERE x.tenant_id=e.tenant_id AND x.task_id=e.task_id AND x.action IN ('验收通过','验收打回') ORDER BY x.created_at DESC,x.id DESC LIMIT 1) WHERE COALESCE(e.review_decision,'')<>'' AND COALESCE(e.reviewer_name,'')='';

UPDATE eam_maintenance_execution e SET reviewed_at=(SELECT x.created_at FROM eam_maintenance_event x WHERE x.tenant_id=e.tenant_id AND x.task_id=e.task_id AND x.action IN ('验收通过','验收打回') ORDER BY x.created_at DESC,x.id DESC LIMIT 1) WHERE COALESCE(e.review_decision,'')<>'' AND e.reviewed_at IS NULL;

CREATE OR REPLACE VIEW v_maintenance_task AS SELECT t.id,t.tenant_id,t.code,t.plan_id,t.equipment_id,t.company_id,t.department_id,t.owner_id,t.status,t.row_version,t.created_at,t.updated_at,t.type_id,t.schedule_id,t.due_date,t.expires_date,JSON_SET(t.snapshot,'$.owners',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_task_person r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.role_code='owner' LIMIT 1),JSON_ARRAY()),'$.reviewers',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_task_person r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.role_code='reviewer' LIMIT 1),JSON_ARRAY())) snapshot,IF(e.task_id IS NULL,NULL,JSON_OBJECT('description',COALESCE(e.`description`,''),'startedAt',COALESCE(DATE_FORMAT(e.`started_at`,'%Y-%m-%dT%H:%i:%s.%f'),''),'startAt',COALESCE(DATE_FORMAT(e.`work_start_at`,'%Y-%m-%dT%H:%i:%s.%f'),''),'endAt',COALESCE(DATE_FORMAT(e.`work_end_at`,'%Y-%m-%dT%H:%i:%s.%f'),''),'items',COALESCE((SELECT JSON_ARRAYAGG(r.item_view) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM v_maintenance_execution_item r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id LIMIT 1),JSON_ARRAY()),'attachments',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',r.file_id,'name',r.name_snapshot,'contentType',r.content_type,'size',r.size_bytes,'url',r.url_snapshot)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_execution_file r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.stage_code='execution' LIMIT 1),JSON_ARRAY()),'acceptance',JSON_OBJECT('reviewerId',COALESCE(CAST(e.reviewer_id AS CHAR),''),'reviewer',COALESCE(e.reviewer_name,''),'reviewedAt',COALESCE(DATE_FORMAT(e.reviewed_at,'%Y-%m-%dT%H:%i:%s.%f'),''),'decision',COALESCE(e.`review_decision`,''),'description',COALESCE(e.`review_description`,''),'score',e.`acceptance_score`,'attachments',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',r.file_id,'name',r.name_snapshot,'contentType',r.content_type,'size',r.size_bytes,'url',r.url_snapshot)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_execution_file r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.stage_code='acceptance' LIMIT 1),JSON_ARRAY())),'collaborators',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_task_person r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.role_code='collaborator' LIMIT 1),JSON_ARRAY()))) result FROM eam_maintenance_task t LEFT JOIN eam_maintenance_execution e ON e.tenant_id=t.tenant_id AND e.task_id=t.id;

UPDATE eam_inspection_execution e SET reviewer_id=(SELECT x.actor_id FROM eam_inspection_event x WHERE x.tenant_id=e.tenant_id AND x.task_id=e.task_id AND x.action IN ('审核通过','审核打回') ORDER BY x.created_at DESC,x.id DESC LIMIT 1) WHERE COALESCE(e.review_decision,'')<>'' AND e.reviewer_id IS NULL;

UPDATE eam_inspection_execution e SET reviewer_name=(SELECT x.actor_name FROM eam_inspection_event x WHERE x.tenant_id=e.tenant_id AND x.task_id=e.task_id AND x.action IN ('审核通过','审核打回') ORDER BY x.created_at DESC,x.id DESC LIMIT 1) WHERE COALESCE(e.review_decision,'')<>'' AND COALESCE(e.reviewer_name,'')='';

UPDATE eam_inspection_execution e SET reviewed_at=(SELECT x.created_at FROM eam_inspection_event x WHERE x.tenant_id=e.tenant_id AND x.task_id=e.task_id AND x.action IN ('审核通过','审核打回') ORDER BY x.created_at DESC,x.id DESC LIMIT 1) WHERE COALESCE(e.review_decision,'')<>'' AND e.reviewed_at IS NULL;

CREATE OR REPLACE VIEW v_inspection_task AS SELECT t.id,t.tenant_id,t.code,t.plan_id,t.equipment_id,t.company_id,t.department_id,t.owner_id,t.status,t.row_version,t.created_at,t.updated_at,t.type_id,t.person_mode,t.kind,t.shift_id,t.due_at,t.expires_at,t.deleted,JSON_SET(t.snapshot,'$.owners',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_task_person r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.role_code='owner' LIMIT 1),JSON_ARRAY()),'$.reviewers',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_task_person r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.role_code='reviewer' LIMIT 1),JSON_ARRAY()),'$.personMode',t.person_mode) snapshot,IF(e.task_id IS NULL,NULL,JSON_OBJECT('description',COALESCE(e.`description`,''),'startedAt',COALESCE(DATE_FORMAT(e.`started_at`,'%Y-%m-%dT%H:%i:%s.%f'),''),'finishedAt',COALESCE(DATE_FORMAT(e.`finished_at`,'%Y-%m-%dT%H:%i:%s.%f'),''),'skipReason',COALESCE(e.`skip_reason`,''),'items',COALESCE((SELECT JSON_ARRAYAGG(r.item_view) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM v_inspection_execution_item r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id LIMIT 1),JSON_ARRAY()),'attachments',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',r.file_id,'name',r.name_snapshot,'contentType',r.content_type,'size',r.size_bytes,'url',r.url_snapshot)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_execution_file r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.stage_code='execution' LIMIT 1),JSON_ARRAY()),'review',JSON_OBJECT('reviewerId',COALESCE(CAST(e.reviewer_id AS CHAR),''),'decision',COALESCE(e.`review_decision`,''),'description',COALESCE(e.`review_description`,''),'reviewer',COALESCE(e.`reviewer_name`,''),'reviewedAt',COALESCE(DATE_FORMAT(e.`reviewed_at`,'%Y-%m-%dT%H:%i:%s.%f'),''),'attachments',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',r.file_id,'name',r.name_snapshot,'contentType',r.content_type,'size',r.size_bytes,'url',r.url_snapshot)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_execution_file r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.stage_code='review' LIMIT 1),JSON_ARRAY())),'scannedEquipmentIds',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.equipment_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_execution_equipment r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.action_code='scan' LIMIT 1),JSON_ARRAY()),'skippedEquipmentIds',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.equipment_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_execution_equipment r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id AND r.action_code='skip' LIMIT 1),JSON_ARRAY()),'reviewItems',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',r.item_key,'decision',r.decision,'description',r.description)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_inspection_execution_review_item r WHERE r.tenant_id=t.tenant_id AND r.task_id=t.id LIMIT 1),JSON_ARRAY()))) result FROM eam_inspection_task t LEFT JOIN eam_inspection_execution e ON e.tenant_id=t.tenant_id AND e.task_id=t.id;
